// No inputs required; value is empty and non-owning.

tensorflow::serving::AnyPtr *any = new tensorflow::serving::AnyPtr();
// Track that this AnyPtr currently holds null.
FUZZ_SET_ATTR_INT(any, "is_null", 1);
// Provide the newly created AnyPtr to the pool as an output.

// Exercise AnyPtr::get<T>() with both matching and mismatched T.
// We temporarily store a pointer of a chosen type into *any, validate get<T>(),
// then reset *any back to null to avoid dangling pointers and delete our temp.

unsigned int choice = *FUZZ_PARAM(unsigned int) % 3; // 0=int, 1=const int, 2=double
if (choice == 0) {
  int *p = new int((int)(*FUZZ_PARAM(unsigned int) & 0x7FFF));
  *any = tensorflow::serving::AnyPtr(p);
  // Matching type succeeds
  int *got_i = any->get<int>();
  FUZZ_ASSERT(got_i != nullptr, "AnyPtr::get<int> must succeed for stored int*");
  // Mismatched type returns nullptr
  const int *got_ci = any->get<const int>();
  (void)got_ci; // may be nullptr
  double *got_d = any->get<double>();
  (void)got_d; // expected nullptr
  // Reset AnyPtr to null before deleting user-owned pointee.
  *any = tensorflow::serving::AnyPtr(nullptr);
  delete p;
  FUZZ_SET_ATTR_INT(any, "is_null", 1);
} else if (choice == 1) {
  // Store as const int to exercise const-qualification matching.
  int *p_nc = new int((int)(*FUZZ_PARAM(unsigned int) & 0x7FFF));
  const int *p = p_nc;
  *any = tensorflow::serving::AnyPtr(p);
  const int *got_ci = any->get<const int>();
  FUZZ_ASSERT(got_ci != nullptr, "AnyPtr::get<const int> must succeed for stored const int*");
  int *got_i = any->get<int>();
  (void)got_i; // expected nullptr due to const mismatch
  // Clean up
  *any = tensorflow::serving::AnyPtr(nullptr);
  delete p_nc; // AnyPtr is non-owning; we delete our allocation.
  FUZZ_SET_ATTR_INT(any, "is_null", 1);
} else {
  double *p = new double((double)(*FUZZ_PARAM(unsigned int) % 10000) / 13.0);
  *any = tensorflow::serving::AnyPtr(p);
  double *got_d = any->get<double>();
  FUZZ_ASSERT(got_d != nullptr, "AnyPtr::get<double> must succeed for stored double*");
  int *got_i = any->get<int>();
  (void)got_i; // expected nullptr
  // Clean up
  *any = tensorflow::serving::AnyPtr(nullptr);
  delete p;
  FUZZ_SET_ATTR_INT(any, "is_null", 1);
}
